+package inventory
+
+import (
+	"reflect"
+	"testing"
+)
+
+func TestLowStockWarehousesOrderedByQuantityThenName(t *testing.T) {
+	stock := map[string]int{
+		"wuhan":    1,
+		"xian":     3,
+		"chengdu":  3,
+		"beijing":  4,
+		"shanghai": 99, // 不是低库存
+	}
+	want := []string{"wuhan", "chengdu", "xian", "beijing"}
+
+	if got := LowStockWarehouses(stock); !reflect.DeepEqual(got, want) {
+		t.Fatalf("LowStockWarehouses = %v, 期望 %v（数量升序，同数量按仓库名升序）", got, want)
+	}
+}
+
+func TestLowStockWarehousesOrderIsDeterministic(t *testing.T) {
+	stock := map[string]int{"wuhan": 2, "chengdu": 2, "xian": 2, "beijing": 2}
+	want := []string{"beijing", "chengdu", "wuhan", "xian"}
+
+	for i := 0; i < 20; i++ {
+		if got := LowStockWarehouses(stock); !reflect.DeepEqual(got, want) {
+			t.Fatalf("第 %d 次 LowStockWarehouses = %v, 期望 %v", i, got, want)
+		}
+	}
+}
