+package inventory
+
+import (
+	"fmt"
+	"reflect"
+	"testing"
+)
+
+// reportOrder 是 LowStockReport 顺序必须对齐的参照。
+func reportOrder(t *testing.T, stock map[string]int) []string {
+	t.Helper()
+	warehouses := LowStockWarehouses(stock)
+	want := make([]string, 0, len(warehouses))
+	for _, warehouse := range warehouses {
+		want = append(want, fmt.Sprintf("%s=%d", warehouse, stock[warehouse]))
+	}
+	return want
+}
+
+func TestLowStockReportMatchesLowStockWarehouses(t *testing.T) {
+	stock := map[string]int{
+		"wuhan":    1,
+		"xian":     3,
+		"chengdu":  3,
+		"beijing":  4,
+		"shanghai": 99, // 不是低库存
+	}
+	want := reportOrder(t, stock)
+
+	if got := LowStockReport(stock); !reflect.DeepEqual(got, want) {
+		t.Fatalf("LowStockReport = %v, 期望 %v（与 LowStockWarehouses 一致）", got, want)
+	}
+}
+
+func TestLowStockReportEntriesAreWarehouseEqualsQuantity(t *testing.T) {
+	stock := map[string]int{"wuhan": 1, "chengdu": 3, "shanghai": 99}
+	report := LowStockReport(stock)
+
+	want := map[string]bool{"wuhan=1": true, "chengdu=3": true}
+	if len(report) != len(want) {
+		t.Fatalf("LowStockReport = %v, 期望 %d 条", report, len(want))
+	}
+	for _, entry := range report {
+		if !want[entry] {
+			t.Fatalf("LowStockReport 含意外条目 %q（低库存条目应为 %v）", entry, want)
+		}
+	}
+}
+
+func TestLowStockReportEmptyStock(t *testing.T) {
+	if got := LowStockReport(map[string]int{}); len(got) != 0 {
+		t.Fatalf("空库存应当是空报告，得到 %v", got)
+	}
+}
