+package inventory
+
+import (
+	"os"
+	"path/filepath"
+	"testing"
+)
+
+// useConfig 把阈值配置文件指到 path，测试结束恢复原值。
+func useConfig(t *testing.T, path string) {
+	t.Helper()
+	original := thresholdsPath
+	thresholdsPath = path
+	t.Cleanup(func() { thresholdsPath = original })
+}
+
+// writeConfig 写一份临时配置，返回它的路径。
+func writeConfig(t *testing.T, content string) string {
+	t.Helper()
+	path := filepath.Join(t.TempDir(), "thresholds.json")
+	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
+		t.Fatalf("写配置文件失败: %v", err)
+	}
+	return path
+}
